"},{"node":"web/src/components/Placeholder/pieces/DESIGN.md","qualified_name":"bench-repo.web.src.components.Placeholder.pieces.DESIGN","label":"Module","file":"web/src/components/Placeholder/pieces/DESIGN.md","start_line":1,"end_line":50,"in_degree":0,"out_degree":0,"match_lines":[40,47,49],"source":"# Placeholder Bird Tilemaps

These SVGs are pixel-art tile strips for the placeholder component. They should read as small game sprites first, not as decorative illustrations.

## Canvas

- Each frame is 32 by 32 pixels.
- A strip width is `32 * frameCount`; the height stays 32.
- The bird should occupy most of the frame. Use the full height when the animal shape supports it.
- Keep a transparent background.
- Use `shape-rendering="crispEdges"` and integer pixel coordinates.

## Naming

- Start with the animal name, for example `Owl` or `Eagle`.
- Add the animation name when needed, for example `OwlBlink` or `EagleIdle`.
- Do not name assets after UI states or empty-state scenarios.

## Frame Count

Frame count is not fixed. Choose it from the animal and animation:

- short blink: usually 3-5 frames
- quiet idle: usually 4-6 frames
- hop or walk: usually 4-8 frames
- flying, diving, or large body motion: usually 6-10 frames

Avoid padding an animation with duplicate frames just to hit a standard count. A frame should change the pose, expression, feather shape, or weight.

## Shared Style

- Use a strong readable silhouette at 1x.
- Prefer chunky pixel clusters over isolated noisy pixels.
- Use a limited palette with one dark outline, one or two body colors, one highlight color, and one accent.
- Keep eyes readable. At this scale, a 2 by 2 eye or a 1 pixel highlight is often better than a single dark pixel.
- Match visual weight between animals. Different species can have different proportions, but the on-screen size should feel comparable.

## Animation

- Make idle motion local: breathing, wing settling, ear feather movement, tail flicks, head turns, and blinking.
- Avoid moving the entire sprite unless the action is hop, fly, recoil, or collapse.
- Preserve the animal identity in every frame. A blink frame should still clearly read as the same bird.
- Keep the first frame a stable readable pose because it is what appears in reduced-motion rendering.

## Current Assets

- `OwlBlink.svg`: five-frame blink/idle strip with breathing wings, blink, and ear-feather settle.
- `EagleIdle.svg`: four-frame idle strip with breathing, blink, alert head shift, and tail flick.
- `ToucanIdle.svg`: four-frame idle strip with beak bob, chest breathing, blink, tail flick, and settle.
"},{"node":"web/src/contexts/AuthContext.tsx","qualified_name":"bench-repo.web.src.contexts.AuthContext","label":"Module","file":"web/src/contexts/AuthContext.tsx","start_line":1,"end_line":197,"in_degree":0,"out_degree":0,"match_lines":[33],"source":"import { useQueryClient } from "@tanstack/react-query";
import { createContext, type ReactNode, useCallback, useContext, useMemo, useState } from "react";
import { clearAccessToken, getAccessToken } from "@/auth-state";
import { authServiceClient, refreshAccessToken, shortcutServiceClient, userServiceClient } from "@/connect";
import { userKeys } from "@/hooks/useUserQueries";
import type { Shortcut } from "@/types/proto/api/v1/shortcut_service_pb";
import type {
  User,
  UserSetting_GeneralSetting,
  UserSetting_TagsSetting,
  UserSetting_WebhooksSetting,
} from "@/types/proto/api/v1/user_service_pb";

interface AuthState {
  currentUser: User | undefined;
  userGeneralSetting: UserSetting_GeneralSetting | undefined;
  userWebhooksSetting: UserSetting_WebhooksSetting | undefined;
  userTagsSetting: UserSetting_TagsSetting | undefined;
  shortcuts: Shortcut[];
  isInitialized: boolean;
  isLoading: boolean;
}

interface AuthContextValue extends AuthState {
  initialize: () => Promise<void>;
  logout: () => Promise<void>;
  refetchSettings: () => Promise<void>;
  setCurrentUser: (user: User | undefined) => void;
}

const AuthContext = createContext<AuthContextValue | null>(null);

/** Settled auth state for a request with no valid session (init finished, not loading). */
const UNAUTHENTICATED_STATE: AuthState = {
  currentUser: undefined,
  userGeneralSetting: undefined,
  userWebhooksSetting: undefined,
  userTagsSetting: undefined,
  shortcuts: [],
  isInitialized: true,
  isLoading: false,
};

export function AuthProvider({ children }: { children: ReactNode }) {
  const queryClient = useQueryClient();
  const [state, setState] = useState<AuthState>({
    currentUser: undefined,
    userGeneralSetting: undefined,
    userWebhooksSetting: undefined,
    userTagsSetting: undefined,
    shortcuts: [],
    isInitialized: false,
    isLoading: true,
  });

  const fetchUserSettings = useCallback(async (userName: string) => {
    const [{ settings }, { shortcuts }] = await Promise.all([
      userServiceClient.listUserSettings({ parent: userName }),
      shortcutServiceClient.listShortcuts({ parent: userName }),
    ]);

    const generalSetting = settings.find((s) => s.value.case === "generalSetting");
    const webhooksSetting = settings.find((s) => s.value.case === "webhooksSetting");
    const tagsSetting = settings.find((s) => s.value.case === "tagsSetting");

    return {
      userGeneralSetting: generalSetting?.value.case === "generalSetting" ? generalSetting.value.value : undefined,
      userWebhooksSetting: webhooksSetting?.value.case === "webhooksSetting" ? webhooksSetting.value.value : undefined,
      userTagsSetting: tagsSetting?.value.case === "tagsSetting" ? tagsSetting.value.value : undefined,
      shortcuts,
    };
  }, []);

  const initialize = useCallback(async () => {
    setState((prev) => ({ ...prev, isLoading: true }));

    // Try to get or refresh the access token.
    // This handles PWA isolated storage scenarios (e.g., iOS Safari) where localStorage
    // may be empty but a valid HTTP-only refresh token cookie still exists.
    // getAccessToken() returns a cached token or loads from localStorage if valid.
    if (!getAccessToken()) {
      try {
        await refreshAccessToken();
      } catch {
        // Refresh failed - no valid session
      }
    }

    // If we still don't have a token after refresh attempt, skip getCurrentUser call
    // to avoid unnecessary network request for unauthenticated users.
    if (!getAccessToken()) {
      setState(UNAUTHENTICATED_STATE);
      return;
    }

    try {
      const { user: currentUser } = await authServiceClient.getCurrentUser({});

      if (!currentUser) {
        clearAccessToken();
        setState(UNAUTHENTICATED_STATE);
        return;
      }

      const settings = await fetchUserSettings(currentUser.name);

      setState({
        currentUser,
        ...settings,
        isInitialized: true,
        isLoading: false,
      });

      // Pre-populate React Query cache
      queryClient.setQueryData(userKeys.currentUser(), currentUser);
      queryClient.setQueryData(userKeys.detail(currentUser.name), currentUser);
    } catch (error) {
      console.error("Failed to initialize auth:", error);
      clearAccessToken();
      setState(UNAUTHENTICATED_STATE);
    }
  }, [fetchUserSettings, queryClient]);

  const logout = useCallback(async () => {
    try {
      await authServiceClient.signOut({});
    } catch (error) {
      console.error("[AuthContext] Failed to sign out:", error);
    } finally {
      clearAccessToken();
      setState(UNAUTHENTICATED_STATE);
      queryClient.clear();
    }
  }, [queryClient]);

  const refetchSettings = useCallback(async () => {
    const currentUserName = state.currentUser?.name;
    if (!currentUserName) {
      return;
    }

    const settings = await fetchUserSettings(currentUserName);
    setState((prev) => {
      if (prev.currentUser?.name !== currentUserName) {
        return prev;
      }
      return { ...prev, ...settings };
    });
  }, [fetchUserSettings, state.currentUser?.name]);

  // Sync the updated user to AuthContext and React Query cache after profile changes
  const setCurrentUser = useCallback(
    (user: User | undefined) => {
      const previousUser = queryClient.getQueryData<User>(userKeys.currentUser());
      setState((prev) => ({ ...prev, currentUser: user }));
      if (user) {
        queryClient.setQueryData(userKeys.currentUser(), user);
        queryClient.setQueryData(userKeys.detail(user.name), user);
      } else {
        queryClient.removeQueries({ queryKey: userKeys.currentUser(), exact: true });
        if (previousUser?.name) {
          queryClient.removeQueries({ queryKey: userKeys.detail(previousUser.name), exact: true });
        }
      }
    },
    [queryClient],
  );

  // Memoize context value to prevent unnecessary re-renders of consumers
  const value = useMemo(
    () => ({
      ...state,
      initialize,
      logout,
      refetchSettings,
      setCurrentUser,
    }),
    [state, initialize, logout, refetchSettings, setCurrentUser],
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error("useAuth must be used within AuthProvider");
  }
  return context;
}

// Convenience hook for just the current user
export function useCurrentUserFromAuth() {
  const { currentUser } = useAuth();
  return currentUser;
}
"},{"node":"web/src/themes/default-dark.css","qualified_name":"bench-repo.web.src.themes.default-dark","label":"Module","file":"web/src/themes/default-dark.css","start_line":1,"end_line":50,"in_degree":0,"out_degree":0,"match_lines":[25],"source":":root {
  /* Surfaces - soft graphite layers for comfortable long-form reading */
  --background: oklch(0.24 0.008 255);
  --foreground: oklch(0.9 0.006 255);

  --card: oklch(0.275 0.009 255);
  --card-foreground: oklch(0.9 0.006 255);

  /* Popovers float above cards without becoming high-glare panels */
  --popover: oklch(0.32 0.01 255);
  --popover-foreground: oklch(0.92 0.006 255);

  /* Primary - readable blue for selected items, links, and focused controls */
  --primary: oklch(0.66 0.11 250);
  --primary-foreground: oklch(0.24 0.008 255);

  /* Secondary - elevated surface for secondary buttons */
  --secondary: oklch(0.33 0.011 255);
  --secondary-foreground: oklch(0.88 0.006 255);

  /* Muted - inline backgrounds for code, skeletons, metadata, and panels */
  --muted: oklch(0.35 0.011 255);
  --muted-foreground: oklch(0.72 0.007 255);

  /* Accent - hover states with a little more color than muted surfaces */
  --accent: oklch(0.39 0.018 250);
  --accent-foreground: oklch(0.94 0.006 255);

  /* Destructive - visible on dark surfaces without overpowering the palette */
  --destructive: oklch(0.64 0.18 24);
  --destructive-foreground: oklch(0.98 0.004 255);

  /* Feedback - success (green) and warning (amber), tuned brighter for dark surfaces */
  --success: oklch(0.7 0.15 155);
  --success-foreground: oklch(0.2 0.03 155);
  --warning: oklch(0.78 0.14 75);
  --warning-foreground: oklch(0.25 0.03 75);

  /* Borders - --border for layout dividers, --input for form field borders */
  --border: oklch(0.38 0.01 255);
  --input: oklch(0.42 0.011 255);
  --ring: oklch(0.58 0.095 250);

  /* Sidebar - anchored but no longer near-black */
  --sidebar: oklch(0.21 0.009 255);
  --sidebar-foreground: oklch(0.76 0.007 255);
  --sidebar-accent: oklch(0.31 0.015 250);
  --sidebar-accent-foreground: oklch(0.9 0.006 255);
}
